<?php
/* TH-Thee Cannabis Co - client site. Rewrites public_html/thd/index.html only.
   Images already on the server are left alone. Backs up what it replaces. */
@ini_set('display_errors','0');
$REPORT=__DIR__.'/thd-report.txt'; $log=[];
function out($s){ global $log,$REPORT; $log[]=$s; @file_put_contents($REPORT,implode("\n",$log)."\n"); echo $s."\n"; }
set_error_handler(function($n,$m,$f,$l){ out("PHP ERROR: $m ($f:$l)"); return true; });
register_shutdown_function(function(){ $e=error_get_last(); if($e && in_array($e['type'],[E_ERROR,E_PARSE,E_COMPILE_ERROR],true)) out('FATAL: '.$e['message']); });
if (($_GET['go'] ?? '') !== 'c0e872ee78fb0afa') { http_response_code(404); exit; }
header('Content-Type: text/plain; charset=utf-8');
@set_time_limit(280);
$ROOT='/home/u732570899/domains/threadedtruthsapparelco.com/public_html';
$F=json_decode(base64_decode(''), true);
if(!is_array($F)){ out('BAD PAYLOAD'); exit; }
$stamp=date('Ymd-His'); $n=0; $baks=0;
foreach($F as $rel=>$b64){
  $p=$ROOT.'/'.$rel;
  $d=dirname($p); if(!is_dir($d)) @mkdir($d,0755,true);
  $body=base64_decode($b64,true);
  if($body===false){ out("BAD BASE64: $rel"); continue; }
  if(is_file($p)){ $bk=$p.'.bak-'.$stamp.'-thd'; if(!is_file($bk) && @copy($p,$bk)) $baks++; }
  if(@file_put_contents($p,$body)===false){ out("WRITE FAILED: $rel"); continue; }
  out("wrote $rel (".strlen($body)." bytes)"); $n++;
}
out('--- DONE. files: '.$n.', backups: '.$baks.' ---');
